/* artem4ik493 — lightweight, dependency-free ambient effects */
(()=>{'use strict';
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const progress=document.createElement('div');progress.className='fx-progress';document.body.append(progress);
let scrollPending=false;function updateScroll(){const max=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max>0?scrollY/max:0})`;scrollPending=false}
addEventListener('scroll',()=>{if(!scrollPending){scrollPending=true;requestAnimationFrame(updateScroll)}},{passive:true});updateScroll();
if(reduce.matches)return;
const fine=matchMedia('(hover:hover) and (pointer:fine)').matches;
if(fine){const glow=document.createElement('div');glow.className='fx-cursor';document.body.append(glow);addEventListener('pointermove',e=>{glow.style.left=e.clientX+'px';glow.style.top=e.clientY+'px';glow.style.opacity='1'},{passive:true});document.querySelectorAll('.card,.project-card,.panel,.tool-card').forEach(card=>{card.classList.add('fx-tilt');card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect();const x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;card.style.setProperty('--fx-x',x*100+'%');card.style.setProperty('--fx-y',y*100+'%');card.style.transform=`perspective(900px) rotateX(${(0.5-y)*5}deg) rotateY(${(x-.5)*5}deg) translateY(-3px)`},{passive:true});card.addEventListener('pointerleave',()=>{card.style.transform=''})})}
const network=document.createElement('div');network.className='fx-network';network.innerHTML='<canvas aria-label="Декоративная схема сетевых узлов"></canvas><span class="fx-network-label">NETWORK / TOPOLOGY</span><span class="fx-network-legend">SIMULATED VISUALIZATION</span>';
const anchor=document.querySelector('#projects')||document.querySelector('main section:nth-of-type(2)');if(anchor){const heading=anchor.querySelector('h2');if(heading)heading.insertAdjacentElement('afterend',network);else anchor.prepend(network)}
const layer=document.createElement('div');layer.className='fx-grid';layer.innerHTML='<canvas aria-hidden="true"></canvas>';document.body.prepend(layer);
const canvases=[layer.querySelector('canvas'),network.querySelector('canvas')];const states=canvases.map((canvas,i)=>({canvas,ctx:canvas.getContext('2d'),nodes:[],w:0,h:0,active:i===0}));
function resize(s){const r=s.canvas.getBoundingClientRect();if(!r.width||!r.height)return;const dpr=Math.min(devicePixelRatio||1,2);s.canvas.width=Math.round(r.width*dpr);s.canvas.height=Math.round(r.height*dpr);s.ctx.setTransform(dpr,0,0,dpr,0,0);s.w=r.width;s.h=r.height;const count=s.active?Math.min(36,Math.max(12,Math.floor(s.w/45))):11;s.nodes=Array.from({length:count},(_,i)=>({x:s.active?Math.random()*s.w:(.1+(i%4)*.27)*s.w+(Math.random()-.5)*30,y:s.active?Math.random()*s.h:(.18+Math.floor(i/4)*.32)*s.h+(Math.random()-.5)*22,vx:(Math.random()-.5)*.16,vy:(Math.random()-.5)*.16,r:s.active?1.2:3+(i%3)}))}
const ro=new ResizeObserver(()=>states.forEach(resize));states.forEach(s=>ro.observe(s.canvas));
let frame=0,visible=true;document.addEventListener('visibilitychange',()=>{visible=!document.hidden});
function draw(){requestAnimationFrame(draw);if(!visible)return;frame++;for(const s of states){if(!s.w)return;const c=s.ctx;c.clearRect(0,0,s.w,s.h);const nodes=s.nodes;for(const n of nodes){n.x+=n.vx;n.y+=n.vy;if(n.x<0||n.x>s.w)n.vx*=-1;if(n.y<0||n.y>s.h)n.vy*=-1}const maxDist=s.active?155:Math.min(260,s.w*.38);for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j],dx=a.x-b.x,dy=a.y-b.y,d=Math.hypot(dx,dy);if(d>maxDist)continue;const alpha=(1-d/maxDist)*(s.active?.17:.48);c.strokeStyle=`rgba(104,167,255,${alpha})`;c.lineWidth=s.active?.7:1.2;c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.stroke();if(!s.active&&(i+j)%5===0){const t=((frame*.004+(i+j)*.13)%1);c.fillStyle='rgba(166,200,255,.95)';c.beginPath();c.arc(a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t,2.2,0,Math.PI*2);c.fill()}}for(const n of nodes){c.fillStyle=s.active?'rgba(104,167,255,.4)':'#68a7ff';c.shadowColor='#68a7ff';c.shadowBlur=s.active?0:14;c.beginPath();c.arc(n.x,n.y,n.r,0,Math.PI*2);c.fill();c.shadowBlur=0}}}
requestAnimationFrame(draw);
})();
